def evolved_p91(x, N, rank, world_size, num_devices,
                 cores_per_device, xm, torch, num_nodes=1):
    # x[i,j] = (-1)^(i+j): +1 when i+j even, -1 when i+j odd. Position-based, no collective.
    idx = torch.arange(N, device=x.device)
    parity = (idx.view(N, 1) + idx.view(1, N)) % 2
    return (1 - 2 * parity).to(x.dtype)

def evolved_p91(x, N, rank, world_size, num_devices,
                 cores_per_device, xm, torch, num_nodes=1):
    # (-1)^(i+j) = (-1)^i * (-1)^j; outer product of sign vector
    s = 1 - 2 * (torch.arange(N, device=x.device) % 2)
    return (s.view(N, 1) * s.view(1, N)).to(x.dtype)

def evolved_p91(x, N, rank, world_size, num_devices,
                 cores_per_device, xm, torch, num_nodes=1):
    row = [[1 if (i + j) % 2 == 0 else -1 for j in range(N)] for i in range(N)]
    return torch.tensor(row, device=x.device, dtype=x.dtype)
